const S = {};
for (const i of $('Load settings').all()) { if (i.json.key) { let v = String(i.json.value == null ? '' : i.json.value).trim(); if (/^(true|false)$/i.test(v)) v = v.toLowerCase(); S[String(i.json.key).trim()] = v; } }
let trig = 'unknown';
for (const n of ['Weekdays hourly 9:05-16:05', 'Run now']) { try { if ($(n).isExecuted) { trig = n; break; } } catch (e) {} }
if (S.paused === 'true') return [{ json: { action: 'halt', reason: 'paused', trigger: trig } }];
const leads = $('Load leads').all().map(i => i.json).filter(r => r && r.id);
const sup = $('Load suppression').all().map(i => i.json);
const supEmails = new Set(sup.map(s => String(s.email || '').trim().toLowerCase()).filter(Boolean));
const supDomains = new Set(sup.map(s => String(s.domain || '').trim().toLowerCase()).filter(Boolean));
const EMAIL_RE = /^[^\s@]+@([^\s@]+\.[a-z]{2,})$/i;
const ACTIVE = ['APPROVED','SENDING','SENT','NEEDS_REVIEW','REPLIED','POSITIVE_INTEREST','MEETING_BOOKED','CUSTOMER'];
const max = Math.max(0, parseInt(S.composer_batch || '3', 10) || 0);
const out = []; let composing = 0;
for (const r of leads) {
  if (String(r.status || '').toUpperCase() !== 'NEW') continue;
  if (composing >= max) break;
  const email = String(r.public_email || '').trim().toLowerCase();
  const m = email.match(EMAIL_RE);
  let reason = ''; let next = 'SKIPPED';
  if (!r.business_name || !r.website || !r.findings) { reason = 'Missing required fields (business name, website or findings).'; next = 'NEEDS_REVIEW'; }
  else if (!email) { reason = 'No public business email. Contact by phone or contact form manually if worthwhile.'; next = 'NEEDS_REVIEW'; }
  else if (!m) { reason = 'Email address syntax is not valid.'; }
  else if (supEmails.has(email) || supDomains.has(m[1])) { reason = 'Address or domain is on the suppression list.'; next = 'SUPPRESSED'; }
  else if (leads.some(o => o.id !== r.id && String(o.public_email || '').trim().toLowerCase() === email && (o.gmail_message_id || o.sent_at || ACTIVE.includes(String(o.status || '').toUpperCase())))) { reason = 'Duplicate: this address belongs to another lead that is active or was already contacted.'; }
  else if (r.no_solicitation_notice === true) { reason = 'Website asks not to be solicited.'; next = 'SUPPRESSED'; }
  else if (!r.email_source_url) { reason = 'No record of the page where the email is published (needed as CASL implied-consent evidence).'; next = 'NEEDS_REVIEW'; }
  if (!reason) composing++;
  out.push({ json: { action: reason ? 'skip' : 'compose', lead_id: r.id, next_status: reason ? next : '', reason: reason, email: email, domain: m ? m[1] : '', trigger: trig, settings: S, lead: r } });
}
if (!out.length) return [{ json: { action: 'halt', reason: 'no NEW leads', trigger: trig } }];
return out;

const j = $input.first().json || {};
let result = 'transient'; let detail = '';
if (j.error) { detail = 'DNS lookup request failed (temporary): ' + String(j.error.message || j.error).slice(0, 200); }
else if (j.Status === 0) {
  const mx = (j.Answer || []).filter(a => a.type === 15);
  const nullMx = mx.length === 1 && /^0\s+\.$/.test(String(mx[0].data || '').trim());
  if (mx.length && !nullMx) { result = 'ok'; detail = 'MX found: ' + mx.map(a => a.data).slice(0, 2).join(', '); }
  else if (nullMx) { result = 'invalid'; detail = 'Domain publishes a null MX: it does not accept email.'; }
  else { result = 'invalid'; detail = 'Domain exists but publishes no MX record (confirmed by DNS).'; }
}
else if (j.Status === 3) { result = 'invalid'; detail = 'Domain does not exist (NXDOMAIN, confirmed by DNS).'; }
else { detail = 'DNS answered with status ' + j.Status + ' (temporary); the lead stays NEW and is retried next run.'; }
return [{ json: { mx_result: result, mx_detail: detail } }];

