const c = $('Loop leads').first().json; const S = c.settings;
const o = $json.output || {};
const min = parseInt(S.min_research_confidence || '50', 10);
const known = String(c.lead.findings || '') + ' ' + String(c.lead.email_source_url || '') + ' ' + String(c.lead.website || '');
const obs = Array.isArray(o.verified_observations) ? o.verified_observations.filter(x => x && x.fact && x.source_url && known.includes(String(x.source_url).replace(/\/$/, ''))) : [];
const conf = Number(o.confidence);
const problems = [];
if (!Number.isFinite(conf)) problems.push('research confidence missing');
else if (conf < min) problems.push('research confidence ' + conf + ' is below ' + min);
